    22	
    23	export function create(data: BookingData): Promise<Booking> {
    24	  return prisma.booking.create({ data });
    25	}
    26	
    27	export function findConflictAtStart(roomId: string, startsAt: Date): Promise<Booking | null> {
    28	  return prisma.booking.findFirst({
    29	    where: {
    30	      roomId,
    31	      status: BOOKING_ACTIVE,
    32	      startsAt: { lte: startsAt },
    33	      endsAt: { gt: startsAt },
    34	    },
    35	  });
    36	}
    37	
    38	export function findById(id: string): Promise<Booking | null> {
    39	  return prisma.booking.findUnique({ where: { id } });
    40	}
    41	
    42	export function list(filter: BookingFilter): Promise<[Booking[], number]> {
    43	  const where: Prisma.BookingWhereInput = {};
    44	  if (filter.roomId) where.roomId = filter.roomId;
    45	  if (filter.userId) where.userId = filter.userId;
    46	  if (filter.status) where.status = filter.status;
    47	  if (filter.from) where.startsAt = { gte: filter.from };
    48	  if (filter.to) where.endsAt = { lte: filter.to };
    49	
    50	  return prisma.$transaction([
    51	    prisma.booking.findMany({
    52	      where,
    53	      take: filter.limit,
    54	      skip: filter.offset,
    55	      orderBy: { startsAt: 'asc' },
    56	    }),
    57	    prisma.booking.count({ where }),
    58	  ]);
    59	}
    60	
    61	export function update(id: string, data: Partial<BookingData>): Promise<Booking> {
    62	  return prisma.booking.update({ where: { id }, data });
    63	}
    64	
    65	export function updateStatus(id: string, status: string): Promise<Booking> {
    66	  return prisma.booking.update({ where: { id }, data: { status } });
    67	}
    68	
    69	export function remove(id: string): Promise<Booking> {
    70	  return prisma.booking.delete({ where: { id } });
    71	}
