import type { Booking } from '@prisma/client';
import { prisma } from '../../db/client.js';
import {
  batchBookingConflict,
  bookingConflict,
  notFound,
  validationFailed,
  type BookingConflictDetail,
  type PeriodDetail,
} from '../../shared/errors.js';
import {
  freeGaps,
  lengthMs,
  overlaps,
  slotsOfLength,
  type Interval,
} from '../../shared/interval.js';
import {
  normalizeLimit,
  normalizeOffset,
  paginated,
  type Page,
} from '../../shared/pagination.js';
import { isBefore, parseInstant } from '../../shared/time.js';
import * as roomRepository from '../rooms/repository.js';
import * as userRepository from '../users/repository.js';
import * as repository from './repository.js';
import { BOOKING_CANCELLED } from './schema.js';
import type {
  CreateBookingInput,
  CreateBookingsInput,
  ListBookingsInput,
  UpdateBookingInput,
} from './schema.js';

/** How many alternative slots a conflict response offers. */
export const MAX_SUGGESTIONS = 3;
/** How far ahead of the requested start we look for those alternatives. */
export const SUGGESTION_LOOKAHEAD_MS = 7 * 24 * 60 * 60 * 1000;

function period(interval: Interval): PeriodDetail {
  return {
    startsAt: interval.startsAt.toISOString(),
    endsAt: interval.endsAt.toISOString(),
  };
}

function parsePeriod(startsAt: string, endsAt: string): Interval {
  const interval = { startsAt: parseInstant(startsAt), endsAt: parseInstant(endsAt) };
  if (!isBefore(interval.startsAt, interval.endsAt)) {
    throw validationFailed('endsAt must be after startsAt', period(interval));
  }
  return interval;
}

/**
 * Free slots of the same length as `wanted`, starting no earlier than the
 * requested start. This is what turns a bare 409 into something the caller can
 * act on without retrying blindly.
 */
async function suggestAlternatives(
  roomId: string,
  wanted: Interval,
  excludeId: string | undefined,
  db: repository.Db,
): Promise<PeriodDetail[]> {
  const window: Interval = {
    startsAt: wanted.startsAt,
    endsAt: new Date(wanted.startsAt.getTime() + SUGGESTION_LOOKAHEAD_MS),
  };
  const busy = await repository.findActiveInRange(
    [roomId],
    window.startsAt,
    window.endsAt,
    db,
  );
  const wantedMs = lengthMs(wanted);
  const gaps = freeGaps(
    window,
    busy.filter((booking) => booking.id !== excludeId),
    wantedMs,
  );
  return slotsOfLength(gaps, wantedMs, MAX_SUGGESTIONS).map(period);
}

async function assertRoomAndUserExist(roomId: string, userId: string): Promise<void> {
  const [room, user] = await Promise.all([
    roomRepository.findById(roomId),
    userRepository.findById(userId),
  ]);
  if (!room) throw notFound('Room');
  if (!user) throw notFound('User');
}

/** Throws a 409 carrying the clashing booking plus usable alternatives. */
async function assertFree(
  roomId: string,
  wanted: Interval,
  excludeId: string | undefined,
  db: repository.Db,
): Promise<void> {
  const conflict = await repository.findConflict(
    { roomId, startsAt: wanted.startsAt, endsAt: wanted.endsAt, excludeId },
    db,
  );
  if (!conflict) return;
  throw bookingConflict(conflict.id, {
    conflictingPeriod: period(conflict),
    requestedPeriod: period(wanted),
    suggestions: await suggestAlternatives(roomId, wanted, excludeId, db),
  });
}

export async function createBooking(input: CreateBookingInput): Promise<Booking> {
  const wanted = parsePeriod(input.startsAt, input.endsAt);
  await assertRoomAndUserExist(input.roomId, input.userId);

  return prisma.$transaction(async (tx) => {
    await assertFree(input.roomId, wanted, undefined, tx);
    return repository.create(
      {
        roomId: input.roomId,
        userId: input.userId,
        title: input.title,
        startsAt: wanted.startsAt,
        endsAt: wanted.endsAt,
      },
      tx,
    );
  });
}

/**
 * Creates every booking or none of them. Callers organising a set of meetings
 * get a single report of everything that clashes instead of a partially
 * applied set they have to unpick.
 */
export async function createBookings(input: CreateBookingsInput): Promise<Booking[]> {
  const items = input.bookings.map((booking, index) => {
    try {
      return { ...booking, ...parsePeriod(booking.startsAt, booking.endsAt) };
    } catch (error) {
      if (error instanceof Error && 'details' in error) {
        Object.assign((error as { details: Record<string, unknown> }).details, { index });
      }
      throw error;
    }
  });

  const rooms = [...new Set(items.map((item) => item.roomId))];
  const users = [...new Set(items.map((item) => item.userId))];
  await Promise.all([
    ...rooms.map(async (roomId) => {
      if (!(await roomRepository.findById(roomId))) throw notFound('Room');
    }),
    ...users.map(async (userId) => {
      if (!(await userRepository.findById(userId))) throw notFound('User');
    }),
  ]);

  return prisma.$transaction(async (tx) => {
    const conflicts: BookingConflictDetail[] = [];

    for (const [index, item] of items.entries()) {
      // A clash with an earlier item of the same batch: no stored booking to
      // point at, so report the sibling index instead.
      const sibling = items.findIndex(
        (other, otherIndex) =>
          otherIndex < index && other.roomId === item.roomId && overlaps(other, item),
      );
      if (sibling !== -1) {
        conflicts.push({
          index,
          conflictsWithIndex: sibling,
          requestedPeriod: period(item),
          conflictingPeriod: period(items[sibling]),
        });
        continue;
      }

      const stored = await repository.findConflict(
        { roomId: item.roomId, startsAt: item.startsAt, endsAt: item.endsAt },
        tx,
      );
      if (stored) {
        conflicts.push({
          index,
          conflictingBookingId: stored.id,
          requestedPeriod: period(item),
          conflictingPeriod: period(stored),
          suggestions: await suggestAlternatives(item.roomId, item, undefined, tx),
        });
      }
    }

    if (conflicts.length > 0) {
      throw batchBookingConflict(conflicts);
    }

    const created: Booking[] = [];
    for (const item of items) {
      created.push(
        await repository.create(
          {
            roomId: item.roomId,
            userId: item.userId,
            title: item.title,
            startsAt: item.startsAt,
            endsAt: item.endsAt,
          },
          tx,
        ),
      );
    }
    return created;
  });
}

export async function getBooking(id: string): Promise<Booking> {
  const booking = await repository.findById(id);
  if (!booking) {
    throw notFound('Booking');
  }
  return booking;
}

export async function listBookings(query: ListBookingsInput): Promise<Page<Booking>> {
  const limit = normalizeLimit(query.limit);
  const offset = normalizeOffset(query.offset);
  const [data, total] = await repository.list({
    roomId: query.roomId,
    userId: query.userId,
    status: query.status,
    from: query.from ? parseInstant(query.from) : undefined,
    to: query.to ? parseInstant(query.to) : undefined,
    limit,
    offset,
  });
  return paginated(data, total, limit, offset);
}

export async function updateBooking(id: string, input: UpdateBookingInput): Promise<Booking> {
  const booking = await getBooking(id);
  const roomId = input.roomId ?? booking.roomId;
  const userId = input.userId ?? booking.userId;
  const wanted = parsePeriod(
    input.startsAt ?? booking.startsAt.toISOString(),
    input.endsAt ?? booking.endsAt.toISOString(),
  );

  if (input.roomId !== undefined || input.userId !== undefined) {
    await assertRoomAndUserExist(roomId, userId);
  }

  // Moving a booking has to respect the same rule as creating one, otherwise
  // a PATCH is a way to double-book a room.
  const moved =
    roomId !== booking.roomId ||
    wanted.startsAt.getTime() !== booking.startsAt.getTime() ||
    wanted.endsAt.getTime() !== booking.endsAt.getTime();
  if (moved && booking.status !== BOOKING_CANCELLED) {
    await assertFree(roomId, wanted, id, prisma);
  }

  return repository.update(id, {
    ...(input.roomId !== undefined ? { roomId } : {}),
    ...(input.userId !== undefined ? { userId } : {}),
    ...(input.title !== undefined ? { title: input.title } : {}),
    ...(input.startsAt !== undefined ? { startsAt: wanted.startsAt } : {}),
    ...(input.endsAt !== undefined ? { endsAt: wanted.endsAt } : {}),
  });
}

export async function cancelBooking(id: string): Promise<Booking> {
  const booking = await getBooking(id);
  if (booking.status === BOOKING_CANCELLED) {
    return booking;
  }
  return repository.updateStatus(id, BOOKING_CANCELLED);
}

export async function deleteBooking(id: string): Promise<void> {
  await getBooking(id);
  await repository.remove(id);
}
