 * Free slots of the same length as `wanted`, starting no earlier than the
 * requested start. This is what turns a bare 409 into something the caller can
 * act on without retrying blindly.
 */
async function suggestAlternatives(
  roomId: string,
  wanted: Interval,
  excludeId: string | undefined,
  db: repository.Db,
): Promise<PeriodDetail[]> {
  const window: Interval = {
    startsAt: wanted.startsAt,
    endsAt: new Date(wanted.startsAt.getTime() + SUGGESTION_LOOKAHEAD_MS),
  };
  const busy = await repository.findActiveInRange(
    [roomId],
    window.startsAt,
    window.endsAt,
    db,
  );
  const wantedMs = lengthMs(wanted);
  const gaps = freeGaps(
    window,
    busy.filter((booking) => booking.id !== excludeId),
    wantedMs,
  );
  return slotsOfLength(gaps, wantedMs, MAX_SUGGESTIONS).map(period);
