  if (!user) throw notFound('User');
}

/** Throws a 409 carrying the clashing booking plus usable alternatives. */
async function assertFree(
  roomId: string,
  wanted: Interval,
  excludeId: string | undefined,
  db: repository.Db,
): Promise<void> {
  const conflict = await repository.findConflict(
    { roomId, startsAt: wanted.startsAt, endsAt: wanted.endsAt, excludeId },
    db,
  );
  if (!conflict) return;
  throw bookingConflict(conflict.id, {
    conflictingPeriod: period(conflict),
    requestedPeriod: period(wanted),
