    const conflicts: BookingConflictDetail[] = [];

    for (const [index, item] of items.entries()) {
      // A clash with an earlier item of the same batch: no stored booking to
      // point at, so report the sibling index instead.
      const sibling = items.findIndex(
        (other, otherIndex) =>
          otherIndex < index && other.roomId === item.roomId && overlaps(other, item),
      );
      if (sibling !== -1) {
        conflicts.push({
          index,
          conflictsWithIndex: sibling,
          requestedPeriod: period(item),
          conflictingPeriod: period(items[sibling]),
        });
        continue;
      }

      const stored = await repository.findConflict(
        { roomId: item.roomId, startsAt: item.startsAt, endsAt: item.endsAt },
        tx,
      );
      if (stored) {
        conflicts.push({
          index,
          conflictingBookingId: stored.id,
          requestedPeriod: period(item),
          conflictingPeriod: period(stored),
          suggestions: await suggestAlternatives(item.roomId, item, undefined, tx),
        });
      }
    }

    if (conflicts.length > 0) {
      throw batchBookingConflict(conflicts);
    }

    const created: Booking[] = [];
    for (const item of items) {
      created.push(
        await repository.create(
          {
            roomId: item.roomId,
            userId: item.userId,
            title: item.title,
            startsAt: item.startsAt,
            endsAt: item.endsAt,
          },
          tx,
        ),
      );
    }
