describe('booking conflict detection', () => {
  let app: FastifyInstance;
  let roomId: string;
  let otherRoomId: string;
  let userId: string;

  beforeAll(async () => {
    app = await createTestApp();
  });

  afterAll(async () => {
    await app.close();
  });

  beforeEach(async () => {
    await resetDb();
    roomId = (
      await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Aurora', capacity: 6 } })
    ).json().id;
    otherRoomId = (
      await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Borealis', capacity: 4 } })
    ).json().id;
    userId = (
      await app.inject({
        method: 'POST',
        url: '/users',
        payload: { name: 'Ada Lovelace', email: 'ada@example.com' },
      })
    ).json().id;
  });

  const payload = (startHours: number, endHours: number, title = 'Sync', room = roomId) => ({
    roomId: room,
    userId,
    title,
    startsAt: inHours(startHours),
    endsAt: inHours(endHours),
  });

  const book = (startHours: number, endHours: number, title = 'Sync', room = roomId) =>
    app.inject({ method: 'POST', url: '/bookings', payload: payload(startHours, endHours, title, room) });

  it('rejects a booking that starts before an existing one and runs into it', async () => {
    await book(24, 25);
    const response = await book(23, 24.5, 'Straddles the left edge');
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects a booking that fully encloses an existing one', async () => {
    await book(24, 25);
    const response = await book(23, 26, 'Encloses');
    expect(response.statusCode).toBe(409);
  });

  it('rejects a booking that matches an existing one exactly', async () => {
    await book(24, 25);
    expect((await book(24, 25, 'Same')).statusCode).toBe(409);
  });

  it('still accepts a booking that ends exactly when another starts', async () => {
    await book(24, 25);
    expect((await book(23, 24, 'Just before')).statusCode).toBe(201);
  });

  it('allows the same period in a different room', async () => {
    await book(24, 25);
    expect((await book(24, 25, 'Elsewhere', otherRoomId)).statusCode).toBe(201);
  });

  it('rejects a period that ends before it starts', async () => {
    const response = await book(25, 24, 'Backwards');
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });

  it('rejects a zero-length period', async () => {
    expect((await book(24, 24, 'Instant')).statusCode).toBe(400);
  });

  it('answers 404 rather than 500 for an unknown room', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { ...payload(24, 25), roomId: 'missing' },
    });
    expect(response.statusCode).toBe(404);
    expect(response.json().error.code).toBe('NOT_FOUND');
  });

  it('answers 404 rather than 500 for an unknown user', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { ...payload(24, 25), userId: 'missing' },
    });
    expect(response.statusCode).toBe(404);
  });

  it('does not let a PATCH move a booking on top of another', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Second');
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.2), endsAt: inHours(24.8) },
    });
    expect(response.statusCode).toBe(409);
  });

  it('does not let a PATCH move a booking into an occupied room', async () => {
    await book(24, 25);
    const second = await book(24, 25, 'Second', otherRoomId);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { roomId },
    });
    expect(response.statusCode).toBe(409);
  });

  it('lets a PATCH keep a booking where it is', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { startsAt: inHours(24), endsAt: inHours(25.5) },
    });
    expect(response.statusCode).toBe(200);
  });

  it('ignores cancelled bookings when checking for conflicts', async () => {
    const first = await book(24, 25);
    await app.inject({ method: 'POST', url: `/bookings/${first.json().id}/cancel` });
    expect((await book(23, 26, 'Reuses the slot')).statusCode).toBe(201);
  });
});

describe('conflict suggestions', () => {
  let app: FastifyInstance;
  let roomId: string;
  let userId: string;

  beforeAll(async () => {
    app = await createTestApp();
  });

  afterAll(async () => {
    await app.close();
