import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest';
import type { FastifyInstance } from 'fastify';
import { createTestApp, resetDb } from './helpers/app.js';

const HOUR = 3_600_000;
const DAY = 24 * HOUR;
// Frozen so payload instants and assertion instants match exactly.
const BASE = Date.now();

function inHours(hours: number): string {
  return new Date(BASE + hours * HOUR).toISOString();
}

interface Slot {
  startsAt: string;
  endsAt: string;
  durationMinutes: number;
}

describe('room availability', () => {
  let app: FastifyInstance;
  let roomId: string;
  let userId: string;

  beforeAll(async () => {
    app = await createTestApp();
  });

  afterAll(async () => {
    await app.close();
  });

  beforeEach(async () => {
    await resetDb();
    roomId = (
      await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Aurora', capacity: 6 } })
    ).json().id;
    userId = (
      await app.inject({
        method: 'POST',
        url: '/users',
        payload: { name: 'Ada Lovelace', email: 'ada@example.com' },
      })
    ).json().id;
  });

  const book = (startHours: number, endHours: number, title = 'Sync') =>
    app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId, title, startsAt: inHours(startHours), endsAt: inHours(endHours) },
    });

  const availability = (query = '') =>
    app.inject({ method: 'GET', url: `/rooms/${roomId}/availability?${query}` });

  const window = (fromHours: number, toHours: number, extra = '') =>
    `from=${encodeURIComponent(inHours(fromHours))}&to=${encodeURIComponent(inHours(toHours))}${extra}`;

  const spans = (slots: Slot[]) => slots.map((slot) => [slot.startsAt, slot.endsAt]);

  it('reports the whole window free for an empty room', async () => {
    const response = await availability(window(24, 32));
    expect(response.statusCode).toBe(200);
    expect(spans(response.json().slots)).toEqual([[inHours(24), inHours(32)]]);
  });

  it('carves booked time out of the free slots', async () => {
    await book(26, 27);
    await book(29, 30, 'Retro');
    expect(spans((await availability(window(24, 32))).json().slots)).toEqual([
      [inHours(24), inHours(26)],
      [inHours(27), inHours(29)],
      [inHours(30), inHours(32)],
    ]);
  });

  it('reports the slot length in minutes', async () => {
    await book(26, 27);
    const slots: Slot[] = (await availability(window(24, 27))).json().slots;
    expect(slots).toHaveLength(1);
    expect(slots[0]?.durationMinutes).toBe(120);
  });

  it('lists the bookings that make the room busy', async () => {
    const created = await book(26, 27);
    const busy = (await availability(window(24, 32))).json().busy;
    expect(busy).toEqual([
      { bookingId: created.json().id, startsAt: inHours(26), endsAt: inHours(27) },
    ]);
  });

  it('only keeps slots long enough for the meeting', async () => {
    await book(25, 26);
    await book(26.5, 32, 'Workshop');
    const slots = (await availability(window(24, 32, '&durationMinutes=45'))).json().slots;
    // The 30-minute gap at 26 is dropped; only 24-25 survives.
    expect(spans(slots)).toEqual([[inHours(24), inHours(25)]]);
  });

  it('echoes the requested duration', async () => {
    expect((await availability(window(24, 32, '&durationMinutes=45'))).json().durationMinutes).toBe(45);
    expect((await availability(window(24, 32))).json().durationMinutes).toBeNull();
  });

  it('returns no slots for a fully booked window', async () => {
    await book(20, 40, 'All day');
    expect((await availability(window(24, 32))).json().slots).toEqual([]);
  });

  it('clips bookings that overrun the window', async () => {
    await book(20, 26, 'Early start');
    expect(spans((await availability(window(24, 32))).json().slots)).toEqual([
      [inHours(26), inHours(32)],
    ]);
  });

  it('ignores cancelled bookings', async () => {
    const created = await book(26, 27);
    await app.inject({ method: 'POST', url: `/bookings/${created.json().id}/cancel` });
    expect(spans((await availability(window(24, 32))).json().slots)).toEqual([
      [inHours(24), inHours(32)],
    ]);
  });

  it('defaults to a week starting now', async () => {
    const body = (await availability()).json();
    expect(new Date(body.to).getTime() - new Date(body.from).getTime()).toBe(7 * DAY);
  });

  it('rejects a window that ends before it starts', async () => {
    const response = await availability(window(32, 24));
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });

  it('rejects a window wider than the maximum', async () => {
    const response = await availability(window(0, 32 * 24));
    expect(response.statusCode).toBe(400);
  });

  it('returns no slots when the meeting cannot fit the window at all', async () => {
    expect((await availability(window(24, 25, '&durationMinutes=180'))).json().slots).toEqual([]);
  });

  it('answers 404 for an unknown room', async () => {
    const response = await app.inject({ method: 'GET', url: '/rooms/missing/availability' });
    expect(response.statusCode).toBe(404);
  });

  it('offers a slot that can actually be booked', async () => {
    await book(26, 27);
    const slot: Slot = (await availability(window(24, 32, '&durationMinutes=60'))).json().slots[0];
    const created = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId, title: 'From availability', startsAt: slot.startsAt, endsAt: slot.endsAt },
    });
    expect(created.statusCode).toBe(201);
  });
});

describe('availability search', () => {
  let app: FastifyInstance;
  let small: string;
  let large: string;
  let userId: string;

  beforeAll(async () => {
    app = await createTestApp();
  });

  afterAll(async () => {
    await app.close();
  });

  beforeEach(async () => {
    await resetDb();
    small = (
      await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Nook', capacity: 2 } })
    ).json().id;
    large = (
      await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Hall', capacity: 20 } })
    ).json().id;
    userId = (
      await app.inject({
        method: 'POST',
        url: '/users',
        payload: { name: 'Ada Lovelace', email: 'ada@example.com' },
      })
    ).json().id;
  });

  const book = (room: string, startHours: number, endHours: number) =>
    app.inject({
      method: 'POST',
      url: '/bookings',
      payload: {
        roomId: room,
        userId,
        title: 'Busy',
        startsAt: inHours(startHours),
        endsAt: inHours(endHours),
      },
    });

  const search = (extra = '') =>
    app.inject({
      method: 'GET',
      url: `/availability?from=${encodeURIComponent(inHours(24))}&to=${encodeURIComponent(inHours(32))}${extra}`,
    });

  const roomIds = (body: { data: { room: { id: string } }[] }) =>
    body.data.map((entry) => entry.room.id);

  it('lists every room that has free time', async () => {
    const body = (await search()).json();
    expect(roomIds(body).sort()).toEqual([small, large].sort());
    expect(body.pagination.total).toBe(2);
  });

  it('leaves out rooms with no free time in the window', async () => {
    await book(small, 20, 40);
    const body = (await search()).json();
    expect(roomIds(body)).toEqual([large]);
    expect(body.pagination.total).toBe(1);
  });

  it('filters by the capacity the meeting needs', async () => {
    expect(roomIds((await search('&capacity=10')).json())).toEqual([large]);
  });

  it('leaves out rooms whose remaining gaps are too short', async () => {
    await book(small, 24, 31.5);
    expect(roomIds((await search('&durationMinutes=60')).json())).toEqual([large]);
  });

  it('returns the free slots for each room', async () => {
    await book(large, 26, 27);
    const body = (await search('&capacity=10')).json();
    expect(body.data[0].slots.map((s: Slot) => [s.startsAt, s.endsAt])).toEqual([
      [inHours(24), inHours(26)],
      [inHours(27), inHours(32)],
    ]);
  });

  it('pages the results', async () => {
    const body = (await search('&limit=1')).json();
    expect(body.data).toHaveLength(1);
    expect(body.pagination).toEqual({ total: 2, limit: 1, offset: 0 });
    const second = (await search('&limit=1&offset=1')).json();
    expect(second.data).toHaveLength(1);
    expect(roomIds(second)).not.toEqual(roomIds(body));
  });

  it('echoes the window it searched', async () => {
    const body = (await search()).json();
    expect(body.from).toBe(inHours(24));
    expect(body.to).toBe(inHours(32));
  });

  it('returns an empty page when nothing matches the capacity', async () => {
    const body = (await search('&capacity=500')).json();
    expect(body.data).toEqual([]);
    expect(body.pagination.total).toBe(0);
  });
});
